def transform(text,old,new):
 updated=rebase_links(text,old,new,mapping,ROOT)
 # Keep unchanged destinations in stationary files byte-for-byte (avoid incidental absolute->relative churn).
 if old==new:
  from research_paths import link_matches
  result=[];end=0
  for mt in link_matches(text):
   path,frag=link_path(mt['target'],old,ROOT)
   if path is None or dest(path)==path:continue
   result.extend([text[end:mt.start()],rebase_links(mt[0],old,new,mapping,ROOT)]);end=mt.end()
  if result:result.append(text[end:]);updated=''.join(result)
  else:updated=text
 # Literal workspace/project paths outside Markdown links also need current destinations.
 for op,np in sorted(mapping.items(),key=lambda x:len(x[0]),reverse=True):
  for prefix in [str(ROOT)+'/', '']:
   updated=updated.replace(prefix+op,prefix+np)
  pp='Projects/from-attention-to-search/'
  if op.startswith(pp):updated=updated.replace(op[len(pp):],np[len(pp):])
 # Resolve literal relative file references inside inline code, leaving job IDs/narrative untouched.
 def code(mt):
  value=mt[1]
  if '\n' in value or not ('/' in value or value.endswith('.md')) or ' ' in value:return mt[0]
  path,frag=link_path(value,old,ROOT)
  if path is None or dest(path)==path:return mt[0]
  target=dest(path);return '`'+(str(target) if value.startswith('/') else os.path.relpath(target,new.parent))+frag+'`'
 updated=re.sub(r'(?<!`)`([^`]+)`(?!`)',code,updated)
 if '15_08_07' in new.name or 'semantic_conditioned_functional_subspace' in new.name or any(x.name.startswith('A15_08_07_') for x in new.parents):
  updated=updated.replace('A15_08_06','A15_08_07')
 if '12_00_short_range' in str(new):updated=updated.replace('A12_0 ','A12_00 ').replace('`A12_0`','`A12_00`')
 return updated
